scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsPortability(new global.EcsAst(engine.rootNode)).sysIds();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-002',
        title: 'Hardcoded sys_id',
        recommendation: 'Look the record up by a stable key (name, number, or a system property holding the sys_id) instead of embedding the sys_id. If the record is delivered with the same update set and the sys_id is stable across instances, mute this finding with a reason.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
